    public void forMethodInvocation(MethodInvocation x) {
        debug("forMethodInvocation ", x,
              " obj = ", x.getObj(),
              " method = ", x.getMethod(),
              " static args = ", x.getStaticArgs(),
              " args = ", x.getArg(),
              " overloading type = " + x.getOverloadingType());
        IdOrOp method = x.getMethod();
        Expr obj = x.getObj();
        List<StaticArg> method_sargs = x.getStaticArgs();
        Expr arg = x.getArg();

        Option<Type> mt = x.getOverloadingType();
        Type domain_type;
        Type range_type;
        if ((mt.isSome())) {
            ArrowType sigtype = (ArrowType) mt.unwrap();
            domain_type = sigtype.getDomain();
            range_type = sigtype.getRange();
        } else {
            // TODO: some method applications (particularly those
            // introduced during getter desugaring) don't have an
            // OverloadingType.  Fix?  Or live with it?
            domain_type = exprType(arg);
            range_type = exprType(x);
        }

        Type receiverType = exprType(obj);
        receiverType = sanitizePossibleStupidIntersectionType(receiverType);
        /* An intersection that none of its conjuncts lies below: the call goes to the
           method's owner among the conjuncts, and the receiver is cast to it. */
        TraitType receiverCast = null;
        if (receiverType instanceof IntersectionType) {
            receiverCast = intersectionMethodOwner(x, (IntersectionType) receiverType, method, mt, domain_type);
            receiverType = receiverCast;
        }
        /* A type variable, at a call of a generic method: the call goes to the method's
           owner among the variable's bounds, and the receiver is cast to it. */
        if (receiverType instanceof VarType && method_sargs.size() > 0) {
            receiverCast = typeVariableMethodOwner(x, (VarType) receiverType, method, mt, domain_type);
            receiverType = receiverCast;
        }
        /* A setter's call, which the desugarer made from an assignment to a field and which
           carries no arrow: the value is passed at the field's type. */
        if (mt.isNone() && method_sargs.isEmpty() && receiverType instanceof TraitType &&
            !(arg instanceof VoidLiteralExpr)) {
            Type setter = setterParamType((TraitType) receiverType, method);
            if (setter != null) domain_type = setter;
        }
//        if (!(receiverType instanceof TraitType)) {
//            throw sayWhat(x, "receiver type "+receiverType+" is not TraitType in " + x);
//        }

        int savedParamCount = paramCount;
        try {

            if (method_sargs.size() > 0) {
                if (obj instanceof AsIfExpr && assumedTrait((AsIfExpr) obj) != null)
                    throw sayWhat(x, ASSUMPTION_GENERIC_METHOD);
                /* Have to emit some interesting code.
                 * 
                 * Want to call object.methodnameSCHEMA
                 * to obtain an object, which we then cast to
                 * an appropriate arrow type (with an explicit leading SELF,
                 * using our static type) which we then invoke.
                 * 
                 * Must pass in a long constant that is the hashcode
                 * (but it could just be a random number, our "hashcode" is the
                 * one that is used everywhere)
                 * 
                 * Must pass in a string correctly describing our static args.
                 * 
                 * The convention for the string must agree with
                 * InstantiatingClassloader.findGenericMethodClosure
                 */

                /*
                 * We will be casting to a particular arrow type;
                 * we need to pass in the receiver type (the prepended first
                 * parameter for the arrow type) to be sure that we get back
                 * exactly the right sort of closure.  There is a variance
                 * problem here: if object extends trait, note that
                 * 
                 * object -> result is NOT a subtype of trait -> result.
                 * 
                 * Contravariance bites us here.
                 */
                StaticArg receiverStaticArg = NodeFactory.makeTypeArg(receiverType);
                List<StaticArg> prepended_method_sargs = Useful.prepend(receiverStaticArg, method_sargs);

                boolean anySymbolic = Useful.orReduction(prepended_method_sargs, isSymbolic);

                boolean one_parameter = genericMethodTakesOneParameter(receiverType, method,
                        method_sargs.size(), domain_type);
                Type prepended_domain = receiverPrependedDomainType(
                        receiverType, domain_type, one_parameter);

                // DRC-WIP

                String string_sargs = NamingCzar.instantiatedGenericDecoration(prepended_method_sargs, thisApi());

                // assumption -- Schema had better be here.
                Type overloading_schema = x.getOverloadingSchema().unwrap();

                TraitType rt_tt = ((TraitType)receiverType);
                List<StaticArg> rt_args = rt_tt.getArgs();

                if (false && rt_args.size() > 0) {
                    // patch linked to use of HEAVY_X in generic method names -- protect the tvars from rewriting.
                    /* 
                     * Must check overloading schema for enclosing trait args.
                     */
                    Map<Id, TypeConsIndex> citc = ci.typeConses();
                    TypeConsIndex tci = citc.get(rt_tt.getName());
                    TraitObjectDecl tod = (TraitObjectDecl) tci.ast();
                    List<StaticParam> rt_params = tod.getHeader().getStaticParams();
                    StaticTypeReplacer str = new StaticTypeReplacer(rt_params, rt_args);
                    overloading_schema = str.replaceIn(overloading_schema);
                }

                String methodName = NamingCzar.genericMethodName(method, (ArrowType) overloading_schema, thisApi());

            // Evaluate the object
            obj.accept(this);
            castReceiver(receiverCast, receiverType);

            String castToArrowType = emitFindGenericMethodClosure(
                    methodName, receiverType, prepended_domain, range_type,
                    string_sargs, anySymbolic);

            // evaluate args
            if (one_parameter && domain_type instanceof TupleType)
                pushTupleBoxed(arg, domain_type);
            else
                evalArg(x, domain_type, arg);

            String sig = NamingCzar.jvmSignatureFor(prepended_domain, range_type, thisApi());

            emitInvokeGenericMethodClosure(sig, castToArrowType);


        } else if (obj instanceof AsIfExpr &&
                   assumedReceiverCall(x, (AsIfExpr) obj, domain_type, range_type)) {
            // the body that the assumed trait gives the method, called statically
        } else {
            if (assumptionCount(callArgList(arg)) > 0 && receiverType instanceof TraitType &&
                methodIsOverloaded((TraitType) receiverType, method, Naming.NO_SELF))
                throw sayWhat(x, ASSUMPTION_PARTIAL_CALL); // the receiver dispatches too
            // put object on stack
            obj.accept(this);
            castReceiver(receiverCast, receiverType);
            // put args on stack
            if (receiverType instanceof TraitType &&
                callTakesTupleBoxed((TraitType) receiverType, method, domain_type)) {
                /* The method takes the tuple as one value (paramTypeAtInstance). */
                pushTupleBoxed(arg, domain_type);
                domain_type = NodeFactory.makeTupleType(NodeUtil.getSpan(domain_type), Useful.list(domain_type));
            } else
                evalArg(x, domain_type, arg);
            methodCall(method, (NamedType)receiverType, domain_type, range_type);
        }
    } finally {
        paramCount = savedParamCount;
    }

}


/**
 * The domain of a generic method's closure, the receiver first: the closure takes the
 * method's parameters as the method declares them (convertGenericMethodToClosureDecl).
 * Where the method has one parameter, its tuple is one value, the closure's second
 * parameter; where it has several, a tuple domain gives one parameter for each.
 *
 * @param receiverType
 * @param domain_type
 * @param one_parameter whether the method declares one parameter
 * @return
 */
private Type receiverPrependedDomainType(Type receiverType, Type domain_type, boolean one_parameter) {
    Type prepended_domain = null;
    if (domain_type instanceof TupleType && !one_parameter) {
        TupleType tt = (TupleType) domain_type;
        prepended_domain = NodeFactory.makeTupleTypeOrType(tt, Useful.prepend(receiverType, tt.getElements()));
    } else {
        prepended_domain = NodeFactory.makeTupleType(domain_type.getInfo().getSpan(), Useful.list(receiverType, domain_type));
    }
    return prepended_domain;
}

/*
 * Whether the generic method that a dotted call names, with nsargs static arguments, at the
 * tuple domain_type, declares one parameter: a generic declaration of the name that the
 * receiver's type holds with nsargs static parameters declares one, and none declares a
 * parameter for each of the tuple's elements.  A declaration of another number of
 * parameters cannot take the call.
 */
private boolean genericMethodTakesOneParameter(Type receiverType, IdOrOp method, int nsargs,
                                               Type domain_type) {
    if (!(domain_type instanceof TupleType) || NodeUtil.isVoidType(domain_type)) return false;
    if (!(receiverType instanceof TraitType)) return false;
    int n = ((TupleType) domain_type).getElements().size();
    boolean one = false;
    for (scala.Tuple3<Functional, StaticTypeReplacer, TraitType> m :
             methodsNamed((TraitType) receiverType, method, Naming.NO_SELF)) {
        Functional fnl = m._1();
        if (fnl.staticParameters().size() != nsargs) continue;
        int k = fnl.parameters().size();
        if (k == 1) one = true;
        else if (k == n) return false;
    }
    return one;
}

/*
 * Whether a dotted call of the method on a receiver of the type t, at the tuple domain_type,
 * passes its argument as one value: each declaration of the method that t holds and that
 * can take the tuple takes it so (paramTypeAtInstance), as a declaration over a type
 * parameter does where t makes it the tuple.  A declaration that takes the tuple's elements,
 * by one parameter of a tuple type or by one parameter for each, keeps them separate.
 */
private boolean callTakesTupleBoxed(TraitType t, IdOrOp method, Type domain_type) {
    if (!(domain_type instanceof TupleType) || NodeUtil.isVoidType(domain_type)) return false;
    int n = ((TupleType) domain_type).getElements().size();
    /* The replacer of a declaration that t's own trait makes holds no static argument
     * of t; this one gives them. */
    StaticTypeReplacer own = null;
    Option<TypeConsIndex> oti = typeAnalyzer.traits().typeCons(t.getName());
    if (!t.getArgs().isEmpty() && oti.isSome() && oti.unwrap() instanceof TraitIndex &&
        ((TraitIndex) oti.unwrap()).staticParameters().size() == t.getArgs().size())
        own = new StaticTypeReplacer(((TraitIndex) oti.unwrap()).staticParameters(), t.getArgs());
    boolean boxed = false;
    for (scala.Tuple3<Functional, StaticTypeReplacer, TraitType> m :
             methodsNamed(t, method, Naming.NO_SELF)) {
        Functional fnl = m._1();
        if (!fnl.staticParameters().isEmpty() || m._2() == null) continue;
        Type declared = NodeUtil.getParamType(fnl.parameters(), NodeUtil.getSpan(method));
        Type instance = m._2().replaceIn(declared);
        if (own != null) instance = own.replaceIn(instance);
        Type at = paramTypeAtInstance(declared, instance);
        if (takesTupleBoxed(at)) {
            if (((TupleType) ((TupleType) at).getElements().get(0)).getElements().size() == n)
                boxed = true;
        } else if (at instanceof TupleType && ((TupleType) at).getElements().size() == n)
            return false;
    }
    return boxed;
}

/*
 * The parameter type, at the receiver's instance, of the setter that a dotted call
 * without the checker's arrow names: the receiver type's one method of the name, without

private LinkedList<Decl> makeGetterSetters(final boolean inTrait,
                                           final Id owner,
                                           final List<Decl> decls) {
    final LinkedList<Decl> result = new LinkedList<Decl>();

    for (Decl decl : decls) {
        decl.accept(new NodeAbstractVisitor_void() {
            public void forVarDecl(VarDecl dec) {
                for (LValue binding : dec.getLhs()) {
                    if (! hidden(binding) &&
                        ! hasExplicitGetter(binding.getName(), decls)) {
                        result.add(makeGetter(inTrait, owner, binding));
                    }
                    if ((settable(binding) || mutable(binding)) &&
                        ! hasExplicitSetter(binding.getName(), decls)) {
                        result.add(makeSetter(inTrait, owner, binding));
                    }
                }
            }
        });
    }
    return result;
}

private List<Decl> mangleDecls(List<Decl> decls) {
    return new NodeUpdateVisitor() {
        public Node forVarDecl(VarDecl that) {
            List<LValue> newLVals = new ArrayList<LValue>();

            for (LValue lval : that.getLhs()) {
                // System.err.println(mangleName(lval.getName()));
                newLVals.add(NodeFactory.makeLValue(lval, mangleName(lval.getName())));
            }
            return NodeFactory.makeVarDecl(NodeUtil.getSpan(that), newLVals, that.getInit());
        }

        /* Do not descend into object expressions. Instead, we mangle their
         * declarations when they're visited by DesugaringVisitor.
         */
        public Node forObjectExpr(ObjectExpr that) {
            return that;
        }
    }.recurOnListOfDecl(decls);
}

private Expr mangleLhs(final Assignment that,
                       final Expr rhs_result,
                       final Option<Type> voidType,
                       final Lhs lhs) {
    assert(that.getLhs().size() == 1);
    final Span span = NodeUtil.getSpan(that);
    final boolean paren = NodeUtil.isParenthesized(that);
    return (Expr)lhs.accept(new NodeUpdateVisitor() {
                public Node forVarRef(VarRef lhs_that) {
                    List<Lhs> left = new ArrayList<Lhs>();
                    left.add((Lhs)lhs_that.accept(DesugaringVisitor.this));
                    return ExprFactory.makeAssignment(span, paren, voidType, left,
                                                      that.getAssignOp(), rhs_result, that.getAssignmentInfos());
                }
                public Node forSubscriptExpr(SubscriptExpr lhs_that) {
                    List<Lhs> left = new ArrayList<Lhs>();
                    left.add((Lhs)lhs_that.accept(DesugaringVisitor.this));
                    return ExprFactory.makeAssignment(span, paren, voidType, left,
                                                      that.getAssignOp(), rhs_result, that.getAssignmentInfos());
                }
                public Node forFieldRef(FieldRef lhs_that) {
                    Expr obj = (Expr) lhs_that.getObj().accept(DesugaringVisitor.this);
                    Expr rhs = rhs_result;
                    if ( that.getAssignOp().isSome() ) {
                        Expr _lhs = (Expr)lhs_that.accept(DesugaringVisitor.this);
                        FunctionalRef op;
                        Option<Type> type;
                        if (!that.getAssignmentInfos().isEmpty()) {
                            op = that.getAssignmentInfos().get(0).getOpForLhs();
                            type = Option.some(((ArrowType) NodeUtil.getExprType(op).unwrap()).getRange());
                        } else {
                            op = that.getAssignOp().unwrap();
                            type = NodeUtil.getExprType(lhs_that);
                        }
                        rhs = ExprFactory.makeOpExpr(span,
                                                     NodeUtil.isParenthesized(lhs_that),
                                                     type,
                                                     op,
                                                     Arrays.asList(_lhs, rhs));
                    }
                    return ExprFactory.makeMethodInvocation(span, NodeUtil.isParenthesized(that),
                                                            voidType, obj,
                                                            lhs_that.getField(),
                                                            rhs);
                }
            });
}

@Override
public Node forAssignment(final Assignment that) {
    final Span span = NodeUtil.getSpan(that);
    final boolean paren = NodeUtil.isParenthesized(that);
    List<Lhs> lhs = that.getLhs();
    int size = lhs.size();
    final Expr rhs_result = (Expr) that.getRhs().accept(this);
    final Option<Type> voidType = Option.<Type>some(NodeFactory.makeVoidType(span));
    if ( size == 1 ) {
        return mangleLhs(that, rhs_result, voidType, lhs.get(0));
    } else {
        /* Desugars
             (x, y.f, z) := e
           to
             tuple_3 = e
             (tuple_0, tuple_1, tuple_2) = tuple_3
             (x := tuple0, y.f(tuple1), z := tuple2)
        */
        Option<FunctionalRef> opr = that.getAssignOp();
        List<Expr>   assigns   = new ArrayList<Expr>();
        List<LValue> secondLhs = new ArrayList<LValue>();
        List<CompoundAssignmentInfo> allAssignmentInfos = that.getAssignmentInfos();
        // Possible shadowing!
        for (int i = size-1; i >= 0; i--) {
            Id id = NodeFactory.makeId(span, "tuple_"+i);
            List<Lhs> left = new ArrayList<Lhs>();
            Lhs _lhs = lhs.get(i);
            left.add(_lhs);
            Expr right = ExprFactory.makeVarRef(span, id);

            // This is the ith constituent assignment, so extract out the
            // ith assignment info.
            List<CompoundAssignmentInfo> assignmentInfo = Collections.emptyList();
            if (!allAssignmentInfos.isEmpty())
                assignmentInfo = Collections.singletonList(allAssignmentInfos.get(i));

            Assignment assign = ExprFactory.makeAssignment(span, paren,
                                                           voidType,
                                                           left, opr,
                                                           right, assignmentInfo);
            assigns.add(0, mangleLhs(assign, right, voidType, _lhs));
            secondLhs.add(0, NodeFactory.makeLValue(id));
        }
        Id id = NodeFactory.makeId(span, "tuple_"+size);
        Expr third = ExprFactory.makeTupleExpr(span, assigns);
        LocalVarDecl second = ExprFactory.makeLocalVarDecl(span, secondLhs,
                                                           ExprFactory.makeVarRef(span, id),
                                                           third);

        Id param = NodeFactory.makeId(span, "param_"+name);
        params.add((Param)NodeFactory.makeParam(param, ty));
        Option<Type> typ = NodeUtil.optTypeOrPatternToType(ty);
        Expr rhs = ExprFactory.makeVarRef(span, typ, param);
        Expr assign;
        if ( boxedRefMap.isSome() ) {
            Map<Pair<Id,Id>,FieldRef> map = boxedRefMap.unwrap();
            Pair<Id,Id> keyPair = new Pair( owner, name );
            if ( map.containsKey( keyPair ) ) {
                FieldRef fieldRef = map.get( keyPair );
                FieldRef rewrite = ExprFactory.makeFieldRef(fieldRef, NodeUtil.getSpan(field));
                assert( rewrite.getObj() instanceof VarRef );
                VarRef obj = (VarRef)rewrite.getObj();
                obj = ExprFactory.makeVarRef(obj, NodeUtil.getExprType(obj),
                                             mangleName(obj.getVarId()));
                assign = ExprFactory.makeMethodInvocation(NodeUtil.getSpan(rewrite), false,
                                                          Option.some(voidType), obj,
                                                          rewrite.getField(), rhs);
            } else {
                List<Lhs> lhs = new ArrayList<Lhs>();
                lhs.add(ExprFactory.makeVarRef(span, typ, mangleName(name)));
                assign = ExprFactory.makeAssignment(span, Option.some(voidType),
                                                    lhs, rhs);
            }
