/*
 * The trait to which a dotted call casts a receiver whose static type is an
 * intersection that none of its conjuncts lies below, as a call typed by the
 * intersection of its candidates' return types is: the conjunct that declares or
 * inherits the called method, the most specific where several do.  The checker
 * finds the method among the methods of the conjuncts that are trait types; where
 * its arrow names the trait that declares the method, only the conjuncts that have
 * that declaration qualify, so that the JVM finds the method at the call's
 * signature; where the call has no arrow, as a getter's, only the conjuncts with a
 * method of the name that takes the call's argument qualify.  Of several conjuncts
 * that neither lies below the other, each has that declaration and the object's
 * class runs its own: the first is taken.
 */
private TraitType intersectionMethodOwner(ASTNode x, IntersectionType it, IdOrOp method,
                                          Option<Type> overloadingType, Type domain) {
    List<TraitType> conjuncts = new ArrayList<TraitType>();
    traitConjuncts(it, conjuncts);
    Id declaring = null;
    if (overloadingType.isSome() && overloadingType.unwrap() instanceof ArrowType) {
        Option<MethodInfo> omi = ((ArrowType) overloadingType.unwrap()).getMethodInfo();
        if (omi.isSome()) {
            Type self = omi.unwrap().getSelfType();
            if (self instanceof TraitSelfType) self = ((TraitSelfType) self).getNamed();
            if (self instanceof TraitType) declaring = ((TraitType) self).getName();
        }
    }
    List<TraitType> owners = new ArrayList<TraitType>();
    for (TraitType c : conjuncts)
        for (scala.Tuple3<Functional, StaticTypeReplacer, TraitType> m : methodsNamed(c, method, Naming.NO_SELF))
            if (declaring == null ? takesArgumentOf(m._1(), domain)
                                  : sameTraitName(m._3().getName(), declaring)) {
                owners.add(c);
                break;
            }
    if (owners.isEmpty())
        throw sayWhat(x, "Can't find the owner of " + method.getText() + " among the conjuncts of " + it);
    for (TraitType c : owners) {
        boolean below = true;
        for (TraitType d : owners)
            if (!typeAnalyzer.lteq(c, d)) { below = false; break; }
        if (below) return c;
    }
    return owners.get(0);
}

/*
 * The trait to which a dotted call of a generic method casts a receiver whose static
 * type is a type variable: the variable's bound that declares or inherits the called
 * method, the most specific where several do, chosen as intersectionMethodOwner
 * chooses among the conjuncts of an intersection.  The bounds are those of the kind
 * environment, a where clause's among them; a bound that is not a trait type is not
 * a candidate.
 */
private TraitType typeVariableMethodOwner(ASTNode x, VarType v, IdOrOp method,
                                          Option<Type> overloadingType, Type domain) {
    scala.Option<StaticParam> sp = typeAnalyzer.env().staticParam(v.getName());
    List<TraitType> bounds = new ArrayList<TraitType>();
    if (sp.isDefined())
        for (BaseType b : sp.get().getExtendsClause()) traitConjuncts(b, bounds);
    if (bounds.isEmpty())
        throw sayWhat(x, "Can't find a trait among the bounds of " + v + " that has " + method.getText());
    return intersectionMethodOwner(x, NodeFactory.makeIntersectionType(NodeUtil.getSpan(v),
                                                                       new ArrayList<Type>(bounds)),
                                   method, overloadingType, domain);
}

/* The trait types among the conjuncts of t, nested intersections opened, in their order. */
private static void traitConjuncts(Type t, List<TraitType> into) {
    if (t instanceof TraitSelfType) t = ((TraitSelfType) t).getNamed();
    if (t instanceof IntersectionType)
        for (Type e : ((IntersectionType) t).getElements()) traitConjuncts(e, into);
    else if (t instanceof TraitType && !into.contains(t))
        into.add((TraitType) t);
}

/* Whether a method can take a call's argument of the type domain by its number of
   parameters: none for the void type, one or the tuple's size for a tuple, else one. */
private static boolean takesArgumentOf(Functional fnl, Type domain) {
    int k = fnl.parameters().size();
    if (NodeUtil.isVoidType(domain)) return k == 0;
    if (domain instanceof TupleType) return k == 1 || k == ((TupleType) domain).getElements().size();
    return k == 1;
}

/* Whether two trait names are one, the api compared where both name one. */
private static boolean sameTraitName(Id a, Id b) {
    if (!a.getText().equals(b.getText())) return false;
    if (a.getApiName().isNone() || b.getApiName().isNone()) return true;
    return a.getApiName().unwrap().getText().equals(b.getApiName().unwrap().getText());
}

/* Casts the receiver on the stack to the class whose method the call names (methodCall):
   a payload object's class, where receiverType, the owner that intersectionMethodOwner
   found or the receiver's own type, is a payload object's; else that owner, if any. */
private void castReceiver(TraitType owner, Type receiverType) {
    String payloadObject = NamingCzar.payloadObjectClass(receiverType);
    if (payloadObject != null)
        mv.visitTypeInsn(CHECKCAST, payloadObject);
    else if (owner != null)
        InstantiatingClassloader.generalizedCastTo(mv, NamingCzar.jvmTypeDesc(owner, thisApi(), false));
}


